reproduction.monitor-ack-policy-quiet2.ps1:
$ErrorActionPreference = 'Stop'
$root = 'C:/W/once-campfire-goose/build'
$log = Join-Path $root 'ack-policy-quiet2-host-monitor.jsonl'
$previous = @{}
Get-Process | Where-Object { $null -ne $_.CPU } | ForEach-Object { $previous[$_.Id] = $_.CPU }
$start = Get-Date
Start-Sleep -Seconds 5
$quiet = 0
$compilerQuiet = 0
while ($quiet -lt 3 -or $compilerQuiet -lt 60) {
    $now = Get-Date
    $seconds = ($now - $start).TotalSeconds
    $processes = @(Get-Process | Where-Object { $null -ne $_.CPU })
    $active = @($processes | Where-Object { $previous.ContainsKey($_.Id) } | ForEach-Object {
        [pscustomobject]@{name=$_.ProcessName; id=$_.Id; cores=[math]::Round(($_.CPU-$previous[$_.Id])/$seconds,3)}
    } | Where-Object { $_.cores -gt 0.3 })
    $compilers = @($processes | Where-Object { $_.ProcessName -in @('cl','clang','clang-cl','link','MSBuild','stage1','stage2','goose','cmake','ninja','rustc','cargo') -and ($_.ProcessName -ne 'MSBuild' -or !$previous.ContainsKey($_.Id) -or (($_.CPU-$previous[$_.Id])/$seconds) -gt 0.01) })
    @{time=$now.ToUniversalTime().ToString('o');phase='waiting';active=$active;compilers=$compilers.Count;residentMSBuild=@($processes | Where-Object ProcessName -eq 'MSBuild' | Select-Object Id,CPU)} | ConvertTo-Json -Compress -Depth 4 | Add-Content $log
    if ($compilers.Count -eq 0) { $compilerQuiet += $seconds } else { $compilerQuiet = 0 }; if ($compilers.Count -eq 0 -and $active.Count -eq 0) { $quiet++ } else { $quiet=0 }
    $previous = @{}; $processes | ForEach-Object { $previous[$_.Id]=$_.CPU }; $start=$now
    Start-Sleep -Seconds 5
}
$p = Start-Process wsl.exe -ArgumentList @('-d','Ubuntu','--','sh','/mnt/c/W/once-campfire-goose/build/measure-ack-policy-quiet2.sh') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $root 'ack-policy-quiet2-measure.log') -RedirectStandardError (Join-Path $root 'ack-policy-quiet2-measure.err')
$lastHeavy=@(); $interrupted=$false
while (!$p.HasExited) {
    $now = Get-Date
    $seconds = ($now - $start).TotalSeconds
    $processes = @(Get-Process | Where-Object { $null -ne $_.CPU })
    $active = @($processes | Where-Object { $previous.ContainsKey($_.Id) } | ForEach-Object {
        [pscustomobject]@{name=$_.ProcessName; id=$_.Id; cores=[math]::Round(($_.CPU-$previous[$_.Id])/$seconds,3)}
    } | Where-Object { $_.cores -gt 0.3 })
    $compilers = @($processes | Where-Object { $_.ProcessName -in @('cl','clang','clang-cl','link','MSBuild','stage1','stage2','goose','cmake','ninja','rustc','cargo') -and ($_.ProcessName -ne 'MSBuild' -or !$previous.ContainsKey($_.Id) -or (($_.CPU-$previous[$_.Id])/$seconds) -gt 0.01) })
    @{time=$now.ToUniversalTime().ToString('o');phase='measurement';active=$active;compilers=$compilers.Count;residentMSBuild=@($processes | Where-Object ProcessName -eq 'MSBuild' | Select-Object Id,CPU)} | ConvertTo-Json -Compress -Depth 4 | Add-Content $log
    $heavy=@($active | Where-Object { $_.cores -gt 0.8 } | ForEach-Object id)
    if (!$interrupted -and ($compilers.Count -gt 0 -or @($heavy | Where-Object { $lastHeavy -contains $_ }).Count -gt 0)) {
        @{time=$now.ToUniversalTime().ToString('o');phase='interruption';reason='Active compiler or sustained unrelated CPU workload'} | ConvertTo-Json -Compress | Add-Content $log
        & wsl.exe -d Ubuntu -- docker kill --signal SIGINT campfire-ack-policy-benchmark
        $interrupted = $LASTEXITCODE -eq 0
    }
    $lastHeavy=$heavy
    $previous = @{}; $processes | ForEach-Object { $previous[$_.Id]=$_.CPU }; $start=$now
    Start-Sleep -Seconds 5
    $p.Refresh()
}
exit $p.ExitCode
